export function pushMusicQueues(queues: MusicQueues): () => void {
  const id = Symbol('music-scope');
  const copy = Object.fromEntries(Object.entries(queues)
    .filter(([, values]) => values !== undefined)
    .map(([slot, values]) => [slot, values!.slice()]));
  const previousQueues = musicQueues;
  (musicQueueScopes ??= new Map()).set(id, copy);
  try {
    applyMusicQueues(Object.assign({}, baseMusicQueues, ...musicQueueScopes.values()));
  } catch (error) {
    musicQueues = previousQueues;
    musicQueueScopes.delete(id);
    if (!musicQueueScopes.size) musicQueueScopes = undefined;
    throw error;
  }
  return () => {
    if (!musicQueueScopes?.delete(id)) return;
    applyMusicQueues(Object.assign({}, baseMusicQueues, ...musicQueueScopes.values()));
    if (!musicQueueScopes.size) musicQueueScopes = undefined;
  };
}
